+            switch (*p)
+            {
+            case 'a': *q++ = '\a'; break;
+            case 'b': *q++ = '\b'; break;
+            case 'f': *q++ = '\f'; break;
+            case 'n': *q++ = '\n'; break;
+            case 'r': *q++ = '\r'; break;
+            case 't': *q++ = '\t'; break;
+            case 'v': *q++ = '\v'; break;
+            default: /* include copying '\', "'" or '"' */
+                *q++ = *p;
+                break;
+            }
+        } else {
+            *q++ = *p;
+        }
+        p++;
+    }
+    *q = 0;
+    *size = (gint)(q - dst);
